# 4. 持久化
# ─────────────────────────────────────────────────────────────────────────────
def load_json():
    if os.path.exists(DB_JSON):
        try:
            with open(DB_JSON, "r", encoding="utf-8") as f:
                return json.load(f)
        except:
            pass
    return None

def save_json(data):
    with open(DB_JSON, "w", encoding="utf-8") as f:
        json.dump(data, f, ensure_ascii=False, default=str)

